<script setup lang="ts">import type {CompatibilityEvidence} from '../../domain/generalCompatibility';import type {CompatibilityLink} from '../../domain/types';import {declarationDefaults} from '../../domain/accessoryCompatibilityQuery';const capabilityLabels={basic:'基本使用','fast-charge':'快充',other:'其他'};defineProps<{evidence?:CompatibilityEvidence[]}>();const verified=(e:CompatibilityEvidence)=>(e.kind==='model'?declarationDefaults(e.record as CompatibilityLink).verification:e.record.verification)==='confirmed'</script>
